const body = $json.body || $json;

// 決定記憶類型
const memoryTypes = {
  'insight': { collection: 'long_term_memory', priority: 'high' },
  'market_data': { collection: 'market_trends', priority: 'medium' },
  'customer': { collection: 'customer_data', priority: 'high' },
  'product': { collection: 'product_knowledge', priority: 'medium' },
  'competitor': { collection: 'competitor_intel', priority: 'high' },
  'learning': { collection: 'long_term_memory', priority: 'low' }
};

const type = body.memory_type || 'learning';
const config = memoryTypes[type] || memoryTypes['learning'];

return [{
  json: {
    ...body,
    _memory_type: type,
    _collection: config.collection,
    _priority: config.priority,
    _committed_at: new Date().toISOString(),
    _retention_until: new Date(Date.now() + 365 * 24 * 60 * 60 * 1000).toISOString()
  }
}];

const output = $json.output || $json.text || '{}';
let compressed = {};
try {
  const match = output.match(/\{[\s\S]*\}/);
  compressed = match ? JSON.parse(match[0]) : { summary: output };
} catch(e) {
  compressed = { summary: output.substring(0, 200) };
}

const original = $('分類記憶類型').item.json;
return [{
  json: {
    ...compressed,
    _original_type: original._memory_type,
    _collection: original._collection,
    _priority: original._priority,
    _committed_at: original._committed_at,
    _vector_text: [
      compressed.summary || '',
      (compressed.key_facts || []).join(' '),
      (compressed.actionable_insights || []).join(' '),
      (compressed.related_topics || []).join(' ')
    ].join(' ')
  }
}];
